package com.productionhouse.crm.legal.rights.service;
import com.productionhouse.crm.legal.contracts.repository.ContractRecordRepository;import com.productionhouse.crm.legal.rights.dto.ContentRightRequest;import com.productionhouse.crm.legal.rights.repository.ContentRightRepository;import com.productionhouse.crm.mediahouse.media.repository.MediaAssetRepository;import com.productionhouse.crm.auth.api.ApiException;import org.junit.jupiter.api.Test;import java.time.LocalDate;import java.util.Optional;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class ContentRightServiceTest{@Test void validatesMediaReferenceAndDateRange(){var rights=mock(ContentRightRepository.class);var media=mock(MediaAssetRepository.class);var service=new ContentRightService(rights,media,mock(ContractRecordRepository.class));var invalid=new ContentRightRequest("Web",null,null,"DISTRIBUTION",2L,null,"IN","web",null,false,LocalDate.parse("2027-02-01"),LocalDate.parse("2027-01-01"),null,"ACTIVE",true);assertThrows(ApiException.class,()->service.create(invalid));var valid=new ContentRightRequest("Web",null,null,"DISTRIBUTION",2L,null,"IN","web",null,false,LocalDate.now(),LocalDate.now().plusDays(2),null,"ACTIVE",true);when(media.findById(2L)).thenReturn(Optional.empty());assertThrows(ApiException.class,()->service.create(valid));}
@Test void reportsPastActiveRightsAsExpiredInExpirationFilters(){var repo=mock(ContentRightRepository.class);var right=new com.productionhouse.crm.legal.rights.entity.ContentRight();right.setName("Old license");right.setRightsType("DISTRIBUTION");right.setStatus("ACTIVE");right.setTerritory("IN");right.setPlatforms("web");right.setStartsAt(LocalDate.now().minusMonths(2));right.setEndsAt(LocalDate.now().minusDays(1));when(repo.findAll(any(org.springframework.data.domain.Sort.class))).thenReturn(java.util.List.of(right));var service=new ContentRightService(repo,mock(MediaAssetRepository.class),mock(ContractRecordRepository.class));var result=service.list(null,"EXPIRED",null,null,null,null,LocalDate.now(),null,0,20,"endsAt","asc");assertEquals(1,result.getTotalElements());assertEquals("EXPIRED",result.getContent().get(0).status());}}
